/**
 * Lines of output that follow the newest line (`design/components/log-view.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/log-view.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  cell,
  elementRef,
  followEnd,
  jumpToEnd,
  mountEffect,
  useMember,
  type Each,
  type IconProps,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/log-view.module.css'
import { Button, type ButtonProps } from '../controls/Button'

export interface LogLine {
  /** Unique in the log and the same on every render: the line's key. */
  id: string
  /** The line as it was written. Whitespace is content. */
  text: string
  /** How serious the line is, drawn as a marker and read as a word. */
  level?: 'info' | 'warning' | 'error'
  /** When the line was written, already formatted by the application. */
  time?: string
  /** What wrote the line, such as a service, a process or a build step. */
  source?: string
}

export interface LogViewMessages {
  /** The label of the button that returns the reader to the newest line. */
  jumpToLatest: string
  /** Read before a line whose level is `info`. */
  info: string
  /** Read before a line whose level is `warning`. */
  warning: string
  /** Read before a line whose level is `error`. */
  error: string
}

/** Lines of output that follow the newest line: the inputs it takes, by the React member's prop names. */
export interface LogViewProps {
  /**
   * The log's accessible name, such as "Build output" in the app's language.
   */
  label: string
  /**
   * The lines to show, oldest first. The application trims the old ones.
   */
  lines: LogLine[]
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: LogViewMessages
  /**
   * Whether more lines are coming, which draws a caret after the last line and sets `aria-busy`.
   */
  streaming?: boolean
  /**
   * Whether a long line wraps, which is the default. `false` keeps each line on one row and
   * scrolls the log sideways, for output whose columns line up.
   */
  wrap?: boolean
}

/** Lines of output that follow the newest line. */
@Component({
  selector: 'pm-log-view',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Button, Icon],
  // prettier-ignore
  template: `<!-- root -->
<div
[attr.class]="e1()"
[attr.data-state]="e2()"
[attr.data-streaming]="e3()"
[attr.data-wrap]="e4()"
data-member="log-view"
><!-- viewport -->
<div
[attr.class]="e5()"
data-log-view-part="viewport"
role="log"
[attr.aria-label]="e6()"
aria-live="off"
[attr.aria-busy]="e7()"
[attr.tabindex]="e8()"
[pmRef]="viewport"
><!-- lines -->
<ol
[attr.class]="e9()"
role="list"
[pmRef]="list"
>@for (line of e10(); track e11(line)) {<!-- line -->
<li
[attr.class]="e12()"
[attr.data-level]="e13(line)"
><!-- marker -->
<span
[attr.class]="e14()"
aria-hidden="true"
>@if (e15(line)) {<pm-icon
[name]="e16(line)"
size="sm"
></pm-icon>}</span>
@if (e15(line)) {<span
[attr.class]="e17(line)"
>{{ e18(line) }}</span>}
@if (e19(line)) {<!-- time -->
<span
[attr.class]="e20(line)"
>{{ e21(line) }}</span>}
<!-- text -->
<span
[attr.class]="e22()"
>@if (e23(line)) {<!-- source -->
<span
[attr.class]="e24(line)"
>{{ e25(line) }}</span>}
<!-- message -->
<span>{{ e26(line) }}</span></span></li>}
@if (e27()) {<!-- end -->
<li
[attr.class]="e28()"
aria-hidden="true"
><span
[attr.class]="e29()"
></span></li>}</ol></div>
<!-- jump -->
<div
[attr.class]="e30()"
><!-- backing -->
<span
[attr.class]="e31()"
><pm-button
variant="outline"
tone="neutral"
size="sm"
icon="down"
[label]="e32()"
(click)="h1()"
></pm-button></span></div></div>`,
})
export class LogView {
  /**
   * The log's accessible name, such as "Build output" in the app's language.
   */
  readonly label = input.required<LogViewProps['label']>()
  /**
   * The lines to show, oldest first. The application trims the old ones.
   */
  readonly lines = input.required<LogViewProps['lines']>()
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  readonly messages = input<Exclude<LogViewProps['messages'], undefined>, LogViewProps['messages']>(
    (() => ({
      jumpToLatest: 'Jump to latest',
      info: 'info',
      warning: 'warning',
      error: 'error',
    }))(),
    {
      transform: (value: LogViewProps['messages']) =>
        value === undefined
          ? (() => ({
              jumpToLatest: 'Jump to latest',
              info: 'info',
              warning: 'warning',
              error: 'error',
            }))()
          : value,
    },
  )
  /**
   * Whether more lines are coming, which draws a caret after the last line and sets `aria-busy`.
   */
  readonly streaming = input<
    Exclude<LogViewProps['streaming'], undefined>,
    LogViewProps['streaming']
  >(false, {
    transform: (value: LogViewProps['streaming']) => (value === undefined ? false : value),
  })
  /**
   * Whether a long line wraps, which is the default. `false` keeps each line on one row and
   * scrolls the log sideways, for output whose columns line up.
   */
  readonly wrap = input<Exclude<LogViewProps['wrap'], undefined>, LogViewProps['wrap']>(true, {
    transform: (value: LogViewProps['wrap']) => (value === undefined ? true : value),
  })
  protected readonly $ = useMember({
    events: [],
    props: {
      label: () => this.label(),
      lines: () => this.lines(),
      messages: () => this.messages(),
      streaming: () => this.streaming(),
      wrap: () => this.wrap(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly detached = cell(() => false)
  protected readonly overflowing = cell(() => false)
  protected readonly list = elementRef<HTMLElement>()
  protected readonly viewport = elementRef<HTMLElement>()
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.detached.value ? 'detached' : undefined
  }

  protected e3() {
    return this.$p.streaming ? '' : undefined
  }

  protected e4() {
    return this.$p.wrap ? '' : undefined
  }

  protected e5() {
    return styles.viewport
  }

  protected e6() {
    return this.$p.label
  }

  protected e7() {
    return this.$p.streaming ? true : undefined
  }

  protected e8() {
    return this.overflowing.value ? '0' : undefined
  }

  protected e9() {
    return styles.lines
  }

  e10() {
    return this.$p.lines
  }

  protected e11(line: Each<ReturnType<LogView['e10']>>) {
    return line.id
  }

  protected e12() {
    return styles.line
  }

  protected e13(line: Each<ReturnType<LogView['e10']>>) {
    return line.level
  }

  protected e14() {
    return styles.marker
  }

  protected e15(line: Each<ReturnType<LogView['e10']>>) {
    return line.level !== undefined
  }

  protected e16(line: Each<ReturnType<LogView['e10']>>): IconProps['name'] {
    if (!(line.level !== undefined)) return undefined as never
    return line.level
  }

  protected e17(line: Each<ReturnType<LogView['e10']>>) {
    if (!(line.level !== undefined)) return undefined as never
    return styles.spoken
  }

  protected e18(line: Each<ReturnType<LogView['e10']>>) {
    if (!(line.level !== undefined)) return undefined as never
    return this.$p.messages[line.level] + ' '
  }

  protected e19(line: Each<ReturnType<LogView['e10']>>) {
    return line.time !== undefined
  }

  protected e20(line: Each<ReturnType<LogView['e10']>>) {
    if (!(line.time !== undefined)) return undefined as never
    return styles.time
  }

  protected e21(line: Each<ReturnType<LogView['e10']>>) {
    if (!(line.time !== undefined)) return undefined as never
    return line.time + ' '
  }

  protected e22() {
    return styles.text
  }

  protected e23(line: Each<ReturnType<LogView['e10']>>) {
    return line.source !== undefined
  }

  protected e24(line: Each<ReturnType<LogView['e10']>>) {
    if (!(line.source !== undefined)) return undefined as never
    return styles.source
  }

  protected e25(line: Each<ReturnType<LogView['e10']>>) {
    if (!(line.source !== undefined)) return undefined as never
    return line.source + ' '
  }

  protected e26(line: Each<ReturnType<LogView['e10']>>) {
    return line.text
  }

  protected e27() {
    return this.$p.streaming
  }

  protected e28() {
    if (!this.$p.streaming) return undefined as never
    return styles.end
  }

  protected e29() {
    if (!this.$p.streaming) return undefined as never
    return styles.caret
  }

  protected e30() {
    return styles.jump
  }

  protected e31() {
    return styles.backing
  }

  protected e32(): ButtonProps['label'] {
    return this.$p.messages.jumpToLatest
  }

  protected h1(): void {
    jumpToEnd(this.viewport.value)
  }

  private effect1(): void {
    this.release1?.()
    const ran = followEnd(this.viewport.value, this.list.value, (state) => {
      this.detached.value = state.detached
      this.overflowing.value = state.overflowing
    })
    this.release1 = () => {
      ran()
    }
  }
}
